const KNOWN_LANGUAGES = new Set(['en', 'fr', 'es', 'zh-Hans', 'zh-Hant', 'ja', 'ko', 'ar']);
const RTL_LANGUAGES = new Set(['ar', 'fa', 'he', 'ur']);
const LOCALIZATION_CACHE_KEY = 'alles-localization';
const CATALOGS = new Map([['en', BUILTIN_ENGLISH]]);
// Generated from the repository-pinned Babel/CLDR territory tender data for
// 2026-07-22. Grouping keeps the complete offline table reviewable and small.
const REGION_CURRENCY_GROUPS = Object.freeze({
  AED: 'AE', AFN: 'AF', ALL: 'AL', AMD: 'AM', AOA: 'AO', ARS: 'AR',
  AUD: 'AU CC CX HM KI NF NR TV', AWG: 'AW', AZN: 'AZ', BAM: 'BA', BBD: 'BB',
  BDT: 'BD', BHD: 'BH', BIF: 'BI', BMD: 'BM', BND: 'BN', BOB: 'BO',
  BRL: 'BR', BSD: 'BS', BWP: 'BW', BYN: 'BY', BZD: 'BZ', CAD: 'CA', CDF: 'CD',
  CHF: 'CH LI', CLP: 'CL', CNY: 'CN', COP: 'CO', CRC: 'CR', CUP: 'CU', CVE: 'CV',
  CZK: 'CZ', DJF: 'DJ', DKK: 'DK FO GL', DOP: 'DO', DZD: 'DZ', EGP: 'EG',
  ERN: 'ER', ETB: 'ET',
  EUR: 'AD AT AX BE BG BL CY DE EA EE ES EU FI FR GF GP GR HR IC IE IT LT LU LV MC ME MF MQ MT NL PM PT RE SI SK SM TF VA XK YT',
  FJD: 'FJ', FKP: 'FK', GBP: 'GB GG GS IM JE TA', GEL: 'GE', GHS: 'GH', GIP: 'GI',
  GMD: 'GM', GNF: 'GN', GTQ: 'GT', GYD: 'GY', HKD: 'HK', HNL: 'HN', HTG: 'HT',
  HUF: 'HU', IDR: 'ID', ILS: 'IL PS', INR: 'BT IN', IQD: 'IQ', IRR: 'IR',
  ISK: 'IS', JMD: 'JM', JOD: 'JO', JPY: 'JP', KES: 'KE', KGS: 'KG', KHR: 'KH',
  KMF: 'KM', KPW: 'KP', KRW: 'KR', KWD: 'KW', KYD: 'KY', KZT: 'KZ', LAK: 'LA',
  LBP: 'LB', LKR: 'LK', LRD: 'LR', LYD: 'LY', MAD: 'EH MA', MDL: 'MD', MGA: 'MG',
  MKD: 'MK', MMK: 'MM', MNT: 'MN', MOP: 'MO', MRU: 'MR', MUR: 'MU', MVR: 'MV',
  MWK: 'MW', MXN: 'MX', MYR: 'MY', MZN: 'MZ', NGN: 'NG', NIO: 'NI',
  NOK: 'BV NO SJ', NPR: 'NP', NZD: 'CK NU NZ PN TK', OMR: 'OM', PAB: 'PA',
  PEN: 'PE', PGK: 'PG', PHP: 'PH', PKR: 'PK', PLN: 'PL', PYG: 'PY', QAR: 'QA',
  RON: 'RO', RSD: 'RS', RUB: 'RU', RWF: 'RW', SAR: 'SA', SBD: 'SB', SCR: 'SC',
  SDG: 'SD', SEK: 'SE', SGD: 'SG', SHP: 'AC SH', SLE: 'SL', SOS: 'SO', SRD: 'SR',
  SSP: 'SS', STN: 'ST', SYP: 'SY', SZL: 'SZ', THB: 'TH', TJS: 'TJ', TMT: 'TM',
  TND: 'TN', TOP: 'TO', TRY: 'TR', TTD: 'TT', TWD: 'TW', TZS: 'TZ', UAH: 'UA',
  UGX: 'UG',
  USD: 'AS BQ DG EC FM GU IO MH MP PR PW SV TC TL UM US VG VI',
  UYU: 'UY', UZS: 'UZ', VES: 'VE', VND: 'VN', VUV: 'VU', WST: 'WS',
  XAF: 'CF CG CM GA GQ TD', XCD: 'AG AI DM GD KN LC MS VC', XCG: 'CW SX',
  XOF: 'BF BJ CI GW ML NE SN TG', XPF: 'NC PF WF', YER: 'YE', ZAR: 'LS NA ZA',
  ZMW: 'ZM', ZWG: 'ZW',
});
const REGION_CURRENCIES = new Map(
  Object.entries(REGION_CURRENCY_GROUPS).flatMap(([currency, regions]) => (
    regions.split(' ').map(region => [region, currency])
  )),
);

let _language = 'en';
let _region = '';
let _timezone = '';
let _clockFormat = 'auto';
let _weekStart = 'auto';
let _currency = '';

function _canonicalLanguage(value) {
  const normalized = String(value || '').trim().toLowerCase();
  return [...KNOWN_LANGUAGES].find(language => language.toLowerCase() === normalized) || '';
}

function _browserRegion() {
  const locale = globalThis.navigator?.language || '';
  if (!locale) return '';
  try {
    return new Intl.Locale(locale).maximize().region || '';
  } catch {
    return String(locale).match(/[-_]([A-Za-z]{2}|[0-9]{3})(?:$|-)/)?.[1]?.toUpperCase() || '';
  }
}

function _dispatch(name, detail) {
  if (typeof window === 'undefined' || typeof CustomEvent === 'undefined') return;
  window.dispatchEvent(new CustomEvent(name, { detail }));
}

function _replace(template, values = {}) {
  return String(template).replace(
    /\{([a-z0-9_]+)\}/gi,
    (_match, name) => String(values[name] ?? ''),
  );
}

function _validCatalog(catalog, language) {
  return catalog?.schema_version === 1
    && catalog?.language === language
    && catalog?.messages
    && typeof catalog.messages === 'object'
    && catalog?.plurals
    && typeof catalog.plurals === 'object';
}

export function installCatalog(catalog) {
  const language = _canonicalLanguage(catalog?.language);
  if (!language || !_validCatalog(catalog, language)) throw new Error('invalid localization catalog');
  CATALOGS.set(language, catalog);
  return catalog;
}

export async function loadCatalog(language, fetcher = globalThis.fetch) {
  const canonical = _canonicalLanguage(language);
  if (!canonical) throw new Error('unknown interface language');
  if (CATALOGS.has(canonical)) return CATALOGS.get(canonical);
  if (typeof fetcher !== 'function') {
    if (canonical === 'en') return CATALOGS.get('en');
    throw new Error('catalog loader unavailable');
  }
  // revalidated, not refetched: a catalog is ~half a megabyte and unchanged between updates
  const response = await fetcher(`/static/locales/${encodeURIComponent(canonical)}.json`, {
    cache: 'no-cache',
    credentials: 'same-origin',
  });
  if (!response?.ok) throw new Error(`could not load ${canonical} catalog`);
  return installCatalog(await response.json());
}

export async function prepareLocalization(settings = {}, fetcher = globalThis.fetch) {
  const requested = _canonicalLanguage(settings.language) || 'en';
  try {
    await loadCatalog(requested, fetcher);
    configureLocalization({ ...settings, language: requested });
    _cacheLocalizationSettings({ ...settings, language: requested });
    translateDocument();
    // server text is a nicety: until it arrives, or if it can't, errors show as the server wrote them
    loadServerMessages(requested, fetcher).catch(() => {});
    return { language: requested, fallback: false };
  } catch (error) {
    configureLocalization({ ...settings, language: 'en' });
    translateDocument();
    const detail = { requested, fallback: 'en', message: error?.message || 'catalog unavailable' };
    _dispatch('alles:localization-error', detail);
    return { language: 'en', fallback: true, error: detail.message };
  }
}

function _cacheLocalizationSettings(settings) {
  try {
    if (typeof window === 'undefined') return;
    window.localStorage?.setItem(LOCALIZATION_CACHE_KEY, JSON.stringify({
      language: _canonicalLanguage(settings.language) || 'en',
      region: String(settings.region || '').toUpperCase(),
      timezone: String(settings.timezone || ''),
      clock_format: ['12', '24'].includes(settings.clock_format) ? settings.clock_format : 'auto',
      week_start: ['mon', 'sun'].includes(settings.week_start) ? settings.week_start : 'auto',
      currency: String(settings.currency || '').toUpperCase(),
    }));
  } catch {
    // Browser storage can be unavailable in hardened/private contexts. The live
    // server setting remains authoritative whenever the server can be reached.
  }
}

export function cachedLocalizationSettings() {
  try {
    if (typeof window === 'undefined') return {};
    const settings = JSON.parse(window.localStorage?.getItem(LOCALIZATION_CACHE_KEY) || '{}');
    return settings && typeof settings === 'object' && _canonicalLanguage(settings.language)
      ? settings
      : {};
  } catch {
    return {};
  }
}

export function localeTag(language = _language, region = _region) {
  const base = _canonicalLanguage(language) || 'en';
  const effectiveRegion = region || _browserRegion();
  const candidate = effectiveRegion ? `${base}-${String(effectiveRegion).toUpperCase()}` : base;
  try {
    return Intl.getCanonicalLocales(candidate)[0];
  } catch {
    return base;
  }
}

export function textDirection(language = _language) {
  return RTL_LANGUAGES.has(String(language).split('-')[0].toLowerCase()) ? 'rtl' : 'ltr';
}

export function configureLocalization(settings = {}) {
  const requested = _canonicalLanguage(settings.language);
  _language = requested && CATALOGS.has(requested) ? requested : 'en';
  const region = String(settings.region || '').toUpperCase();
  _region = /^(?:[A-Z]{2}|[0-9]{3})$/.test(region) ? region : '';
  const timezone = String(settings.timezone || '');
  try {
    if (timezone) new Intl.DateTimeFormat('en', { timeZone: timezone }).format();
    _timezone = timezone;
  } catch {
    _timezone = '';
  }
  _clockFormat = ['12', '24'].includes(settings.clock_format) ? settings.clock_format : 'auto';
  _weekStart = ['mon', 'sun'].includes(settings.week_start) ? settings.week_start : 'auto';
  const currency = String(settings.currency || '').toUpperCase();
  _currency = /^[A-Z]{3}$/.test(currency) ? currency : '';
  if (typeof document !== 'undefined') {
    document.documentElement.lang = localeTag();
    document.documentElement.dir = textDirection();
  }
  _dispatch('alles:localization-change', localizationState());
  return localizationState();
}

export function localizationState() {
  const effectiveRegion = _region || _browserRegion();
  return {
    language: _language,
    region: _region,
    effectiveRegion,
    timezone: _timezone,
    clockFormat: _clockFormat,
    weekStart: _weekStart,
    currency: _currency,
    effectiveCurrency: _currency || REGION_CURRENCIES.get(effectiveRegion) || '',
    locale: localeTag(),
    direction: textDirection(),
  };
}

export function t(key, values = {}) {
  const template = CATALOGS.get(_language)?.messages?.[key]
    ?? CATALOGS.get('en')?.messages?.[key]
    ?? key;
  return _replace(template, values);
}

export function tp(key, count, values = {}) {
  const category = new Intl.PluralRules(localeTag()).select(Number(count));
  const forms = CATALOGS.get(_language)?.plurals?.[key]
    ?? CATALOGS.get('en')?.plurals?.[key];
  if (!forms) return key;
  return _replace(forms[category] ?? forms.other, { ...values, count });
}

// the server writes its refusals and errors in english. each language has a file that maps that
// english (f-string messages as "{name}" templates) to its own, built by scripts/server_messages.py
const SERVER_TEXT = { language: 'en', exact: new Map(), templates: [] };
const SLOT = /\{([a-z][a-z0-9_]*)\}/i;

export function installServerMessages(language, messages = {}) {
  const exact = new Map();
  const templates = [];
  for (const [english, own] of Object.entries(messages)) {
    if (!SLOT.test(english)) {
      exact.set(english, own);
      continue;
    }
    const names = [];
    const pattern = english.split(/(\{[a-z][a-z0-9_]*\})/i).map(part => {
      const slot = part.match(/^\{([a-z][a-z0-9_]*)\}$/i);
      if (!slot) return part.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      names.push(slot[1]);
      return '([\\s\\S]+?)';
    }).join('');
    // the template with the most fixed words wins when two could match
    templates.push({ re: new RegExp(`^${pattern}$`), names, own, weight: english.replace(/\{[^}]+\}/g, '').length });
  }
  templates.sort((a, b) => b.weight - a.weight);
  Object.assign(SERVER_TEXT, { language: _canonicalLanguage(language) || 'en', exact, templates });
}

function _serverMatch(text) {
  if (SERVER_TEXT.exact.has(text)) return SERVER_TEXT.exact.get(text);
  for (const { re, names, own } of SERVER_TEXT.templates) {
    const hit = text.match(re);
    if (hit) return _replace(own, Object.fromEntries(names.map((name, i) => [name, hit[i + 1]])));
  }
  return null;
}

// server text in the reader's language; anything unknown stays as the server wrote it
export function serverText(text) {
  const value = String(text ?? '');
  if (SERVER_TEXT.language !== _language || !value) return value;
  const whole = _serverMatch(value.trim());
  if (whole != null) return whole;
  // "upload failed: <server detail>": the lead is ours already, the rest came from the server
  const cut = value.indexOf(': ');
  const tail = cut > 0 ? _serverMatch(value.slice(cut + 2).trim()) : null;
  return tail != null ? `${value.slice(0, cut)}: ${tail}` : value;
}

export async function loadServerMessages(language, fetcher = globalThis.fetch) {
  const canonical = _canonicalLanguage(language);
  if (!canonical || canonical === 'en' || typeof fetcher !== 'function') {
    installServerMessages('en');
    return;
  }
  const response = await fetcher(`/static/locales/server/${encodeURIComponent(canonical)}.json`, {
    cache: 'no-cache',
    credentials: 'same-origin',
  });
  if (!response?.ok) throw new Error(`could not load ${canonical} server messages`);
  installServerMessages(canonical, (await response.json()).messages);
}

// 'one', 'two', 'few' or 'other' for 1st, 2nd, 3rd, 4th in the interface language
export function ordinalCategory(n) {
  return new Intl.PluralRules(localeTag(), { type: 'ordinal' }).select(Number(n));
}

function _options(options = {}, includeClock = false) {
  const value = { ...options };
  if (_timezone && !('timeZone' in value)) value.timeZone = _timezone;
  if (includeClock && !('hour12' in value) && !('hourCycle' in value)) {
    if (_clockFormat === '12') value.hour12 = true;
    if (_clockFormat === '24') value.hour12 = false;
  }
  return value;
}

export function formatDate(value, options = {}) {
  return new Intl.DateTimeFormat(localeTag(), _options(options)).format(new Date(value));
}

export function formatCalendarDate(value, options = {}) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(value || ''));
  if (!match) return String(value || '');
  const [year, month, day] = match.slice(1).map(Number);
  const date = new Date(0);
  date.setUTCHours(0, 0, 0, 0);
  date.setUTCFullYear(year, month - 1, day);
  if (
    date.getUTCFullYear() !== year
    || date.getUTCMonth() !== month - 1
    || date.getUTCDate() !== day
  ) return String(value || '');
  return new Intl.DateTimeFormat(localeTag(), { ...options, timeZone: 'UTC' }).format(date);
}

export function formatDateForLocale(value, locale, options = {}) {
  return new Intl.DateTimeFormat(locale || 'en', options).format(new Date(value));
}

export function formatTime(value, options = {}) {
  return new Intl.DateTimeFormat(localeTag(), _options(options, true)).format(new Date(value));
}

export function formatTimeForLocale(value, locale, options = {}) {
  return new Intl.DateTimeFormat(locale || 'en', options).format(new Date(value));
}

// a server wall clock ("19:30") read the way every time in the app reads: the same short time
// style reminders show next to their date, in the owner's 12/24-hour choice
export function formatClock(hhmm) {
  const match = /^(\d{1,2}):(\d{2})$/.exec(String(hhmm || ''));
  if (!match) return String(hhmm || '');
  return new Intl.DateTimeFormat(localeTag(), _options({ timeStyle: 'short', timeZone: 'UTC' }, true))
    .format(new Date(Date.UTC(2000, 0, 1, Number(match[1]), Number(match[2]))));
}

export function formatDateTime(value, options = {}) {
  const fields = Object.keys(options).length
    ? options
    : { dateStyle: 'medium', timeStyle: 'short' };
  return new Intl.DateTimeFormat(localeTag(), _options(fields, true)).format(new Date(value));
}

export function formatDateParts(value, options = {}) {
  return new Intl.DateTimeFormat(localeTag(), _options(options, true)).formatToParts(new Date(value));
}

export function resolvedTimeZone() {
  return chosenTimeZone() || 'UTC';
}

// the zone the owner set, else the browser's own. '' when the browser won't say: then the
// server shouldn't be told 'UTC' as if someone chose it
export function chosenTimeZone() {
  if (_timezone) return _timezone;
  try {
    return Intl.DateTimeFormat().resolvedOptions().timeZone || '';
  } catch {
    return '';
  }
}

export function calendarDateKey(value = new Date()) {
  const parts = new Intl.DateTimeFormat('en', {
    calendar: 'gregory',
    numberingSystem: 'latn',
    timeZone: resolvedTimeZone(),
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(new Date(value));
  const fields = Object.fromEntries(parts.map(part => [part.type, part.value]));
  return `${fields.year}-${fields.month}-${fields.day}`;
}

export function formatNumber(value, options = {}) {
  return new Intl.NumberFormat(localeTag(), options).format(Number(value));
}

export function formatCurrency(value, currency = localizationState().effectiveCurrency, options = {}) {
  if (!currency) return formatNumber(value, options);
  return new Intl.NumberFormat(localeTag(), {
    style: 'currency',
    currency,
    ...options,
  }).format(Number(value));
}

// a country or region named in the interface language; the fallback is the english name
export function regionName(code, fallback = code) {
  try {
    return new Intl.DisplayNames([localeTag()], { type: 'region' }).of(String(code).toUpperCase()) || fallback;
  } catch {
    return fallback;
  }
}

export function formatList(values, options = {}) {
  return new Intl.ListFormat(localeTag(), options).format(values.map(value => String(value)));
}

export function formatRelativeTime(value, unit, options = {}) {
  return new Intl.RelativeTimeFormat(localeTag(), options).format(Number(value), unit);
}

export function translateDocument(root = globalThis.document) {
  if (!root?.querySelectorAll) return;
  root.querySelectorAll('[data-i18n]').forEach(element => {
    const value = t(element.dataset.i18n);
    if (value !== element.dataset.i18n) element.textContent = value;
  });
  root.querySelectorAll('[data-i18n-code]').forEach(element => {
    const value = t(element.dataset.i18nCode);
    if (value === element.dataset.i18nCode) return;
    // `backticks` in a message mark the parts that stay as code
    const doc = root.ownerDocument || root;
    element.replaceChildren(...value.split('`').map((part, index) => {
      if (index % 2 === 0) return doc.createTextNode(part);
      const code = doc.createElement('code');
      code.textContent = part;
      return code;
    }));
  });
  root.querySelectorAll('[data-i18n-placeholder]').forEach(element => {
    const value = t(element.dataset.i18nPlaceholder);
    if (value !== element.dataset.i18nPlaceholder) element.setAttribute('placeholder', value);
  });
  root.querySelectorAll('[data-i18n-aria-label]').forEach(element => {
    const value = t(element.dataset.i18nAriaLabel);
    if (value !== element.dataset.i18nAriaLabel) element.setAttribute('aria-label', value);
  });
  root.querySelectorAll('[data-i18n-title]').forEach(element => {
    const value = t(element.dataset.i18nTitle);
    if (value !== element.dataset.i18nTitle) element.setAttribute('title', value);
  });
}
